insert into public.helplines (name, number, description_en, description_bn, hours, category, is_toll_free, source_url, verified_at, sort_order) values
  ('National Emergency Service', '999', 'Toll-free national call centre providing emergency police, fire service and ambulance services.', 'পুলিশ, ফায়ার সার্ভিস ও অ্যাম্বুলেন্সের জরুরি সেবা দেয় এমন টোল-ফ্রি জাতীয় কল সেন্টার।', '24/7', 'emergency', true, 'https://telecom-police.portal.gov.bd/pages/static-pages/695e3b0cc4774958d7b72321', '2026-09-26', 1),
  ('National Helpline Centre for Violence Against Women and Children', '109', 'National helpline under the Ministry of Women and Children Affairs'' Multi-Sectoral Programme on Violence Against Women that gives women and child victims of violence and their families information, advice and referral to support services.', 'নারী নির্যাতন প্রতিরোধে মহিলা ও শিশুবিষয়ক মন্ত্রণালয়ের মাল্টিসেক্টরাল প্রোগ্রামের জাতীয় হেল্পলাইন। নির্যাতনের শিকার নারী ও শিশু এবং তাদের পরিবারকে তথ্য, পরামর্শ এবং সহায়তা সেবায় রেফারাল দেয়।', '24/7', 'women_children', true, 'https://dwa.gov.bd/site/page/d2f28455-6c23-4d74-9c89-ff377be01dc2/-', '2026-09-26', 4),
  ('Child Helpline', '1098', 'Free helpline run by the Department of Social Services (with UNICEF support) where a child, or anyone on a child''s behalf, can seek help for violence, abuse or exploitation; provides information, immediate action and telephone counselling.', 'সমাজসেবা অধিদফতর পরিচালিত (ইউনিসেফের সহায়তায়) বিনামূল্যের হেল্পলাইন। সহিংসতা, নির্যাতন বা শোষণের শিকার শিশু, অথবা শিশুর পক্ষে যে কেউ সাহায্য চাইতে পারেন; তথ্য, তাৎক্ষণিক ব্যবস্থা ও টেলিফোনে কাউন্সেলিং দেওয়া হয়।', '24/7', 'child', true, 'https://dss.gov.bd/pages/static-pages/6922e007933eb65569e2519a', '2026-09-26', 5),
  ('National Helpline', '333', 'Government national helpline (a2i, ICT Division) for information on government services, complaints about social issues such as child marriage and violence against women and children, and assistance during emergencies or disasters.', 'সরকারি সেবার তথ্য, বাল্যবিবাহ ও নারী-শিশু নির্যাতনের মতো সামাজিক সমস্যার অভিযোগ এবং দুর্যোগ বা জরুরি অবস্থায় সহায়তার জন্য সরকারের জাতীয় হেল্পলাইন (এটুআই, আইসিটি বিভাগ)।', '24/7', 'information', false, 'https://bangladesh.gov.bd/site/page/79d371f2-4530-437a-982f-16c7c0a2ecad', '2026-09-26', 7),
  ('Shastho Batayon (Health Call Centre)', '16263', 'DGHS health call centre where callers can speak directly to a doctor about any health matter (press 0), get information on government hospitals and doctors, get ambulance information, or lodge complaints; the official page does not mention mental-health counselling.', 'স্বাস্থ্য অধিদপ্তরের স্বাস্থ্য কল সেন্টার: যেকোনো স্বাস্থ্য বিষয়ে সরাসরি ডাক্তারের সঙ্গে কথা বলা, সরকারি হাসপাতাল ও ডাক্তারের তথ্য, অ্যাম্বুলেন্সের তথ্য বা অভিযোগ জানানো যায়। অফিসিয়াল পাতায় মানসিক স্বাস্থ্য কাউন্সেলিংয়ের উল্লেখ নেই।', '24/7', 'health', false, 'https://16263.dghs.gov.bd/', '2026-09-26', 6),
  ('Moner Bondhu Helpline', '+8801776632344', 'Helpline of Moner Bondhu, a Dhaka-based mental health organisation offering online and in-person counselling; the site describes a 24/7 hotline.', 'ঢাকাভিত্তিক মানসিক স্বাস্থ্য সংস্থা মনের বন্ধুর হেল্পলাইন; সংস্থাটি অনলাইন ও সরাসরি কাউন্সেলিং দেয়। ওয়েবসাইট অনুযায়ী হটলাইনটি ২৪/৭ খোলা।', '24/7', 'emotional_support', false, 'https://monerbondhu.com/', '2026-09-26', 2),
  ('SHOJON tele mental health service (SAJIDA Foundation)', '09606119900', 'SAJIDA Foundation''s tele mental health service providing confidential phone support for anyone facing mental distress.', 'মানসিক কষ্টে থাকা যে কারও জন্য সাজিদা ফাউন্ডেশনের গোপনীয় টেলিফোন মানসিক স্বাস্থ্যসেবা।', '10:00–22:00', 'emotional_support', false, 'https://shojon.sajida.org/', '2026-09-26', 3),
  ('Vent by Mindspace', '09678678778', 'Anonymous psychological crisis hotline run by Mindspace, a mental health organisation.', 'মানসিক স্বাস্থ্য সংস্থা মাইন্ডস্পেস পরিচালিত, পরিচয় গোপন রাখা মানসিক সংকট হটলাইন।', '18:00–06:00', 'emotional_support', false, 'https://mindspacebd.com/', '2026-09-26', 3)
insert into public.support_organizations (name_en, name_bn, kind, services, description_en, description_bn, division_slug, city, address, phone, website, is_free, source_url, verified_at) values
  ('National Institute of Mental Health (NIMH), Dhaka', 'জাতীয় মানসিক স্বাস্থ্য ইনস্টিটিউট', 'government', array['psychiatry', 'clinical psychology', 'psychotherapy', 'child & adolescent psychiatry', 'addiction psychiatry', 'emergency']::text[], 'Government national mental health institute at Sher-e-Bangla Nagar, Dhaka, with departments including adult, child/adolescent/family, addiction and geriatric psychiatry, psychotherapy & clinical psychology, and an emergency department.', 'শেরেবাংলা নগর, ঢাকায় অবস্থিত সরকারি জাতীয় মানসিক স্বাস্থ্য ইনস্টিটিউট। এখানে প্রাপ্তবয়স্ক, শিশু-কিশোর ও পারিবারিক, মাদকাসক্তি ও বয়োবৃদ্ধ মনোরোগবিদ্যা, সাইকোথেরাপি ও ক্লিনিক্যাল সাইকোলজি বিভাগ এবং জরুরি বিভাগ রয়েছে।', 'dhaka', 'Dhaka', 'শেরেবাংলা নগর, ঢাকা-১২০৭ (Sher-e-Bangla Nagar, Dhaka-1207)', '+88 02-22337409, +88 02-22337410', 'https://nimh.gov.bd/', null, 'https://nimh.gov.bd/contact.php', '2026-09-26'),
  ('Pabna Mental Hospital', 'পাবনা মানসিক হাসপাতাল', 'hospital', array['psychiatric outpatient', 'inpatient', 'addiction treatment', 'counselling by clinical psychologists']::text[], 'Government psychiatric hospital in Himayetpur, Pabna. Its outpatient department is open daily except public holidays, 8:00 am to 2:30 pm. Outpatients receive 7 days of medicine free, and clinical psychologists and psychiatric social workers counsel patients and guardians.', 'পাবনার হিমায়েতপুরে অবস্থিত সরকারি মানসিক হাসপাতাল। বহির্বিভাগ সরকারি ছুটির দিন ছাড়া প্রতিদিন সকাল ৮টা থেকে দুপুর ২টা ৩০ মিনিট পর্যন্ত খোলা। বহির্বিভাগের রোগীরা ৭ দিনের ওষুধ বিনামূল্যে পান, এবং ক্লিনিক্যাল সাইকোলজিস্ট ও সাইকিয়াট্রিক সোশ্যাল ওয়ার্কাররা রোগী ও অভিভাবকদের কাউন্সেলিং করেন।', 'rajshahi', 'Pabna', 'মানসিক হাসপাতাল, পাবনা। ডাকঘর: হিমায়েতপুর, পাবনা সদর, পাবনা। (Mental Hospital, PO Himayetpur, Pabna Sadar, Pabna)', '02588846231, 02588805212', 'https://mentalhospital.pabna.gov.bd/', null, 'https://mentalhospital.pabna.gov.bd/pages/static-pages/697ff42335ce18e1c06dca58', '2026-09-26'),
  ('Department of Psychiatry, Bangladesh Medical University (BMU, formerly BSMMU)', null, 'hospital', array['psychiatry']::text[], 'Psychiatry department of Bangladesh Medical University, the country''s premier postgraduate medical university in Shahbag, Dhaka, which also provides general and specialised clinical care as a tertiary hospital. The department page does not describe its clinical services.', 'শাহবাগ, ঢাকায় অবস্থিত দেশের শীর্ষস্থানীয় স্নাতকোত্তর মেডিক্যাল বিশ্ববিদ্যালয় বাংলাদেশ মেডিক্যাল বিশ্ববিদ্যালয়ের মনোরোগবিদ্যা বিভাগ। বিশ্ববিদ্যালয়টি টারশিয়ারি হাসপাতাল হিসেবে সাধারণ ও বিশেষায়িত চিকিৎসা দেয়। বিভাগের পাতায় এর চিকিৎসাসেবার বিবরণ নেই।', 'dhaka', 'Dhaka', 'Shahbag, Dhaka-1000, Bangladesh', '+88-02-55165708 (university main line)', 'https://psychiatry.bmu.ac.bd/', null, 'https://www.bmu.ac.bd/about', '2026-09-26'),
  ('National Trauma Counseling Centre (NTCC)', 'জাতীয় ট্রমা কাউন্সিলিং সেন্টার', 'government', array['psychosocial counselling', 'trauma counselling', 'family counselling']::text[], 'Centre under the Ministry of Women and Children Affairs'' Multi-Sectoral Programme on Violence Against Women, based in the Department of Women Affairs building, providing psychosocial counselling and support to women and child victims of violence.', 'নারী নির্যাতন প্রতিরোধে মহিলা ও শিশুবিষয়ক মন্ত্রণালয়ের মাল্টিসেক্টরাল প্রোগ্রামের অধীন কেন্দ্র, মহিলাবিষয়ক অধিদপ্তর ভবনে অবস্থিত। নির্যাতনের শিকার নারী ও শিশুদের মনোসামাজিক কাউন্সেলিং ও সহায়তা দেয়।', 'dhaka', 'Dhaka', 'Department of Women Affairs Building, 37/3 Eskaton Garden Road, Dhaka-1000 (building address from dwa.gov.bd)', null, 'https://mowca.gov.bd/pages/static-pages/694032a235ce18e1c055fb4c', null, 'https://mowca.gov.bd/pages/static-pages/694032a235ce18e1c055fb4c', '2026-09-26'),
  ('Moner Bondhu', null, 'ngo', array['online counselling', 'in-person counselling', 'psychiatrist consultation', 'corporate wellbeing', '24/7 helpline']::text[], 'Mental health organisation offering online and in-person counselling (in person at its Lalmatia wellbeing space), psychiatrist consultations, courses and a 24/7 hotline. It describes its service as affordable and professional; sessions are booked (paid).', 'অনলাইন ও সরাসরি (লালমাটিয়ায়) কাউন্সেলিং, সাইকিয়াট্রিস্ট পরামর্শ, কোর্স এবং ২৪/৭ হটলাইন সেবা দেওয়া মানসিক স্বাস্থ্য সংস্থা। সেশন বুক করে নিতে হয় (সশুল্ক)।', 'dhaka', 'Dhaka', '2/16, Block B (8th floor), Lalmatia, Dhaka', '+8801776632344', 'https://monerbondhu.com/', false, 'https://monerbondhu.com/', '2026-09-26'),
  ('SAJIDA Foundation - SHOJON tele mental health and Sajida Trauma Counseling Centre', null, 'ngo', array['tele-counselling', 'trauma counselling', 'psychosocial support']::text[], 'SAJIDA Foundation runs SHOJON, a phone-based tele mental health service (10 am-10 pm), and the Sajida Trauma Counseling Centre, which offers free, confidential trauma counselling, including at Narayanganj 300 Bed Hospital.', 'সাজিদা ফাউন্ডেশন টেলিফোনভিত্তিক মানসিক স্বাস্থ্যসেবা SHOJON (সকাল ১০টা থেকে রাত ১০টা) এবং সাজিদা ট্রমা কাউন্সেলিং সেন্টার পরিচালনা করে। সেন্টারটি নারায়ণগঞ্জ ৩০০ শয্যা হাসপাতালসহ বিভিন্ন স্থানে বিনামূল্যে, গোপনীয় ট্রমা কাউন্সেলিং দেয়।', 'dhaka', 'Narayanganj (centre); nationwide by phone', 'Trauma Counseling Centre: Narayanganj 300 Bed Hospital, Room 23/02, 1st Floor (Beside ICU)', '09606119900 (SHOJON)', 'https://www.sajida.org/sajidas-approach/fostering-equity/mental-health/', null, 'https://www.sajida.org/sajidas-approach/fostering-equity/mental-health/', '2026-09-26'),
  ('Mindspace (Vent crisis hotline)', null, 'ngo', array['crisis hotline', 'counselling', 'screening tests', 'workshops']::text[], 'Mental health organisation offering affordable counselling, free anxiety/depression/stress screening tests and the anonymous Vent crisis hotline (6 PM-6 AM).', 'সাশ্রয়ী কাউন্সেলিং, উদ্বেগ, বিষণ্নতা ও চাপ যাচাইয়ের বিনামূল্যের স্ক্রিনিং টেস্ট এবং পরিচয় গোপন রাখা Vent সংকট হটলাইন (সন্ধ্যা ৬টা থেকে সকাল ৬টা) পরিচালনাকারী মানসিক স্বাস্থ্য সংস্থা।', null, null, null, '09678678778', 'https://mindspacebd.com/', null, 'https://mindspacebd.com/', '2026-09-26'),
  ('NSU Counseling & Wellbeing Center, North South University', null, 'university', array['counselling (NSU students, faculty, staff only)', 'group sessions', 'referral']::text[], 'Primary mental health care unit for North South University students, faculty and staff, offering various therapeutic approaches and referral advice. It is not open to the general public.', 'নর্থ সাউথ বিশ্ববিদ্যালয়ের শিক্ষার্থী, শিক্ষক ও কর্মীদের প্রাথমিক মানসিক স্বাস্থ্যসেবা কেন্দ্র; বিভিন্ন থেরাপি পদ্ধতি ও রেফারাল পরামর্শ দেয়। সাধারণ মানুষের জন্য উন্মুক্ত নয়।', 'dhaka', 'Dhaka', 'North South University, Bashundhara, Dhaka-1229', '+880-2-55668200', 'https://www.northsouth.edu/resources/cwc.html', null, 'https://www.northsouth.edu/resources/cwc.html', '2026-09-26'),
  ('Bangladesh Clinical Psychology Society (BCPS)', null, 'professional_body', array['professional body', 'member lists']::text[], 'Professional society for clinical psychology in Bangladesh. Its website publishes lists of its members.', 'বাংলাদেশে ক্লিনিক্যাল সাইকোলজির পেশাজীবী সংগঠন। এর ওয়েবসাইটে সদস্যদের তালিকা প্রকাশ করা হয়।', 'dhaka', 'Dhaka', null, null, 'https://bcps.org.bd/', null, 'https://bcps.org.bd/', '2026-09-26')
insert into public.practitioners (full_name, title, profession, credentials, organization, specialties, languages, division_slug, city, modes, booking_url, profile_url, source_url, verified_at) values
  ('Dr. Farzana Rahman', 'Consultant in Psychiatry', 'psychiatrist', 'MBBS, MD (Psychiatry)', 'Evercare Hospital Dhaka', array['Mood Disorders', 'Anxiety Disorders', 'Substance Use Disorder', 'OCD', 'Eating Disorders']::text[], array['bn', 'en']::text[], 'dhaka', 'Dhaka', array['in_person']::text[], 'https://www.evercarebd.com/en/dhaka/appointment?name=dr-farzana-rahman-psychiatry', 'https://www.evercarebd.com/en/dhaka/doctors/dr-farzana-rahman-psychiatry', 'https://www.evercarebd.com/en/dhaka/doctors/dr-farzana-rahman-psychiatry', '2026-09-26'),
  ('Dr. Nigar Sultana', 'Consultant in Psychiatry', 'psychiatrist', 'MBBS, MD (USA), ABPN Board Certification (Adult Psychiatry; Child and Adolescent Psychiatry)', 'Evercare Hospital Dhaka', array['Adult Psychiatry', 'Child and Adolescent Psychiatry', 'ADHD', 'Autism', 'Mood Disorder']::text[], array['bn', 'en']::text[], 'dhaka', 'Dhaka', array['in_person']::text[], 'https://www.evercarebd.com/en/dhaka/appointment?name=dr-nigar-sultana', 'https://www.evercarebd.com/en/dhaka/doctors/dr-nigar-sultana', 'https://www.evercarebd.com/en/dhaka/doctors/dr-nigar-sultana', '2026-09-26'),
  ('Ms. Alya Fardous Azad', 'Senior Counsellor, Counselling Centre', 'counsellor', 'BSc (Psychology), MSc (Clinical Psychology), Dhaka University', 'Evercare Hospital Dhaka', array['Clinical Psychology', 'Counselling']::text[], array['bn', 'en']::text[], 'dhaka', 'Dhaka', array['in_person']::text[], 'https://www.evercarebd.com/en/dhaka/appointment?name=ms-alya-fardous-azad', 'https://www.evercarebd.com/en/dhaka/doctors/ms-alya-fardous-azad', 'https://www.evercarebd.com/en/dhaka/doctors/ms-alya-fardous-azad', '2026-09-26'),
  ('Mrs. Sharmin Haque', 'Clinical Psychologist', 'clinical_psychologist', 'MSc, M.Phil in Clinical Psychology', 'Square Hospitals Ltd.', array['Clinical Psychology']::text[], '{}'::text[], 'dhaka', 'Dhaka', array['in_person']::text[], 'https://www.squarehospital.com/appointment/20090500011', 'https://www.squarehospital.com/doctors/19', 'https://www.squarehospital.com/doctors/19', '2026-09-26'),
